style.css:
@-moz-document domain("roblox.com") {
/* Target the master container wrappers and completely strip background colors */
    html, body, 
    .dark-theme, .gotham-theme, 
    #container-main, .content, 
    .container-fluid, #wrap,
    .main-layout, .page-content {
        background-image: url("https://imgur.com") !important;
        background-color: transparent !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Force the home grid content zone to be transparent so the picture is exposed */
    .container-main, #container-main, .content {
        background: transparent !important;
    }

    /* Transform solid grey dashboard cards into frosted glass tiles */
    .section,
    .section-content, 
    .game-card-container, 
    .item-card-container, 
    .container-header,
    .places-list-container,
    .tab-content,
    .dialog-container,
    .profile-header,
    .left-navigation-container {
        background: rgba(11, 12, 16, 0.65) !important;
        backdrop-filter: blur(8px) !important;
        border-radius: 14px !important;
        border: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* Keep page typography perfectly visible on the new dark background image */
    h1, h2, h3, h4, h5, p, span, a, 
    .text, .text-name, .game-card-name, .text-title,
    .left-nav-label {
        color: #ffffff !important;
        text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8) !important;
    }

    /* Wipe away stubborn sub-menu color blocks */
    .rbx-tabs-horizontal .nav-tabs, 
    .section-content-off,
    .menu-vertical,
    .stack,
    #navigation {
        background: transparent !important;
    }

    /* Darken the top menu header panel so navigation tabs remain crisp */
    #header, .rbx-header {
        background: rgba(7, 8, 10, 0.85) !important;
        backdrop-filter: blur(12px) !important;
    }
}
